import{_ as r,I as t,c as n,o as d,j as e,ap as o,a as l,J as s}from"./chunks/framework.BVMg0REN.js";const x=JSON.parse('{"title":"任务运行","description":"","frontmatter":{},"headers":[],"relativePath":"FAQ/05-runtime-issues.md","filePath":"zh/FAQ/05-runtime-issues.md","lastUpdated":1783261160000}'),h={name:"FAQ/05-runtime-issues.md"},c={id:"任务运行",tabindex:"-1"};function u(b,a,m,p,P,f){const i=t("Badge");return d(),n("div",null,[e("h1",c,[a[0]||(a[0]=l("任务运行")),s(i,{type:"danger",text:"问题"}),a[1]||(a[1]=l()),a[2]||(a[2]=e("a",{class:"header-anchor",href:"#任务运行","aria-label":"Permalink to “任务运行”"},"​",-1))]),a[3]||(a[3]=o('<h2 id="运行相关" tabindex="-1">运行相关 <a class="header-anchor" href="#运行相关" aria-label="Permalink to “运行相关”">​</a></h2><h3 id="雷电模拟器" tabindex="-1">雷电模拟器 <a class="header-anchor" href="#雷电模拟器" aria-label="Permalink to “雷电模拟器”">​</a></h3><ul><li>关闭自动旋转屏幕：设置 → 其他设置 → 关闭。</li><li>调整分辨率：设置 → 性能设置 → 推荐「手机版-720×1280-DPI240」</li></ul><h3 id="连接正常-但是操作卡顿、异常、频繁出错或显示任务已完成" tabindex="-1">连接正常，但是操作卡顿、异常、频繁出错或显示任务已完成 <a class="header-anchor" href="#连接正常-但是操作卡顿、异常、频繁出错或显示任务已完成" aria-label="Permalink to “连接正常，但是操作卡顿、异常、频繁出错或显示任务已完成”">​</a></h3><ul><li>异形屏UI适配设为0。</li><li>主页 → 启动游戏 → 齿轮 → 选择正确游戏客户端版本。</li><li>Adb Input触控模式慢属正常，自动战斗建议换其他模式。</li><li>繁中适配持续优化中，请保持<code>MaaYuan</code>为最新版本。</li></ul><h3 id="运行任务后无反应或持续点击模拟器某处" tabindex="-1">运行任务后无反应或持续点击模拟器某处 <a class="header-anchor" href="#运行任务后无反应或持续点击模拟器某处" aria-label="Permalink to “运行任务后无反应或持续点击模拟器某处”">​</a></h3><ul><li>重启MaaYuan</li><li>多开冲突：检查模拟器端口与<code>MaaYuan</code>显示端口是否一致。</li><li>后台保活：取消勾选「后台挂机时保活运行」（右上角菜单 → 设置中心 → 其他）。</li><li>检查分辨率：确保分辨率为720*1280。</li><li>更换触控方式：在<code>MaaYuan</code>设置 → 连接设置 中，选择其他触控方式进行尝试。</li></ul><h3 id="biubiu加速器无法启动" tabindex="-1">biubiu加速器无法启动 <a class="header-anchor" href="#biubiu加速器无法启动" aria-label="Permalink to “biubiu加速器无法启动”">​</a></h3><p>请将此任务放在启动游戏任务之前，此任务只负责加速不负责启动游戏。（如果加速了就启动是因为biubiu有加速自动启动游戏的功能）</p><h3 id="截图用时过长-触控反应时间过长" tabindex="-1">截图用时过长/触控反应时间过长 <a class="header-anchor" href="#截图用时过长-触控反应时间过长" aria-label="Permalink to “截图用时过长/触控反应时间过长”">​</a></h3><ul><li>截图耗时≤1000ms属正常。</li><li>启用GPU加速推理（<code>MaaYuan</code>设置 → 高级设置），核显/老旧独显（如GTX 750Ti以下）不建议开启；遇bug则关闭。</li><li><strong>检查分辨率</strong>：<a href="./XXX.html">新手教学</a>。</li></ul><h3 id="启动游戏无法运行" tabindex="-1">启动游戏无法运行 <a class="header-anchor" href="#启动游戏无法运行" aria-label="Permalink to “启动游戏无法运行”">​</a></h3><ul><li>请根据客户端-系统设置-游戏语言，选择<code>MaaYuan</code>的资源类型，港服务必确认此项。</li></ul><table><tbody><tr><td align="center">游戏语言</td><td align="center" colspan="2">繁中</td><td align="center" colspan="2">简中</td></tr><tr><td align="center">游戏名</td><td align="center" colspan="3">代号鸢</td><td align="center">如鸢</td></tr><tr><td align="center">官服</td><td align="center">台服</td><td align="center" colspan="2">港服</td><td align="center">国服/官网</td></tr><tr><td align="center">其他版本</td><td align="center" colspan="3">/</td><td align="center">Tap/九游/小米/华为/OPPO</td></tr></tbody></table><ul><li>关于Tap版本，在数据中客户端的名称与官网下载是不同的，如果不需要执行任务列表中的<strong>启动游戏</strong>，可无视此差异。</li></ul><h2 id="任务相关" tabindex="-1">任务相关 <a class="header-anchor" href="#任务相关" aria-label="Permalink to “任务相关”">​</a></h2><h3 id="_6-24-7-15运行失败" tabindex="-1">6-24/7-15运行失败 <a class="header-anchor" href="#_6-24-7-15运行失败" aria-label="Permalink to “6-24/7-15运行失败”">​</a></h3><ul><li>确认模拟器分辨率为720*1280。</li><li>未通第六章时，先进入第六章并停在6-24关卡外，再开始任务。</li><li><strong>MuMu模拟器</strong>：取消勾选「后台挂机时保活运行」（右上角菜单 → 设置中心 → 其他）。</li><li>DPI≥180（过低会导致画面模糊、OCR识别错误）。</li><li><code>MaaYuan</code>设置 → 高级设置 → 关闭GPU加速。</li><li>卡在主线章节滑动？重装<code>MaaYuan</code>。</li></ul><h3 id="每日进膳任务失败" tabindex="-1">每日进膳任务失败 <a class="header-anchor" href="#每日进膳任务失败" aria-label="Permalink to “每日进膳任务失败”">​</a></h3><ul><li>更换代号鸢/如鸢游戏背景（UI更新需反馈完整截图等待适配）；</li><li>调换每日进膳与据点任务顺序。</li></ul><h3 id="心纸营建卡在宝箱处" tabindex="-1">心纸营建卡在宝箱处 <a class="header-anchor" href="#心纸营建卡在宝箱处" aria-label="Permalink to “心纸营建卡在宝箱处”">​</a></h3><p>OCR识别偶有误差，已优化，仍遇问题请反馈。</p><h2 id="作业相关" tabindex="-1">作业相关 <a class="header-anchor" href="#作业相关" aria-label="Permalink to “作业相关”">​</a></h2><h3 id="如何保证自动战斗的正确运行" tabindex="-1">如何保证自动战斗的正确运行 <a class="header-anchor" href="#如何保证自动战斗的正确运行" aria-label="Permalink to “如何保证自动战斗的正确运行”">​</a></h3><ul><li>战斗页面右侧详情/自动/倍速条保持展开。</li><li>按作者站位摆放密探，确保密探核心命盘一致（尤其+能量）。</li><li><code>MaaYuan</code>无法探查技能使用，需完美对轴。</li></ul><h3 id="放入作业后提示-资源加载失败-导致无法连接模拟器" tabindex="-1">放入作业后提示“资源加载失败”，导致无法连接模拟器 <a class="header-anchor" href="#放入作业后提示-资源加载失败-导致无法连接模拟器" aria-label="Permalink to “放入作业后提示“资源加载失败”，导致无法连接模拟器”">​</a></h3><ul><li>作业json需放<code>resource\\copilot-cache</code>下。</li><li>推荐神秘代码导入，若仍有问题，换作业尝试，有问题的文件在官方群找管理处理。</li><li>取消激活或删除导入作业，删除后重启，不行则重装。</li></ul><h3 id="神秘代码导入失败" tabindex="-1">神秘代码导入失败 <a class="header-anchor" href="#神秘代码导入失败" aria-label="Permalink to “神秘代码导入失败”">​</a></h3><p>网络问题致无法与作业站通讯，可下载json本地导入或稍后重试。</p><h3 id="打到第七回合自动结束" tabindex="-1">打到第七回合自动结束 <a class="header-anchor" href="#打到第七回合自动结束" aria-label="Permalink to “打到第七回合自动结束”">​</a></h3><ul><li>确保未选抄完几回合后自动停止。</li><li>调整模拟器分辨率至720*1280后尝试。</li><li>还不行就用战斗中开始抄作业，从第七回合开始。</li></ul><h3 id="抄作业失败" tabindex="-1">抄作业失败 <a class="header-anchor" href="#抄作业失败" aria-label="Permalink to “抄作业失败”">​</a></h3><ul><li>0s 结束为未激活作业，检查作业是否导入并激活，正确激活作业运行后会提示作业版本信息：“作业信息：由 MaaYuan Share vXXX生成，需MaaYuan vXXX 上运行。”，为例行提示，如能正常运行则无需理会；</li><li>10 - 20s 左右结束为未识别到指定内容（如自动刷洞窟的“前往讨伐”；自动抄作业的“开始战斗”；回合内开始抄作业的右上角“回合X”），检查开始任务的游戏界面是否正确。</li><li>导入神秘代码后无法连接/提示资源加载失败/抄作业无信息、无法运行，下载最新版本MaaYuan同时确保作业是近期生成的。</li></ul>',33))])}const _=r(h,[["render",u]]);export{x as __pageData,_ as default};
